/// `schemas/project.schema.json` (generated by tools/codegen/project-schema.fsx) against the schema
/// records and real projects, and the worked example in docs/examples.
module FarmEngine.Authoring.Tests.ProjectSchemaTests

open System
open System.IO
open System.Reflection
open Microsoft.FSharp.Reflection
open Xunit
open FarmEngine.Authoring
open FarmEngine.Authoring.Net
open FarmEngine.Authoring.Tests.TestProjects
open FarmEngine.Schemas

let private repo (parts: string list) =
    Path.Combine(Array.ofList (__SOURCE_DIRECTORY__ :: ".." :: ".." :: parts))

let private schema =
    lazy
        (match Json.parse (File.ReadAllText(repo [ "schemas"; "project.schema.json" ])) with
         | Ok json -> json
         | Error message -> failwith message)

let private defs () =
    match Json.get "$defs" schema.Value with
    | JObject defs -> defs
    | _ -> failwith "no $defs"

/// The JSON Schema keywords the generator writes, checked against a value: the paths that fail.
let rec private validate (path: string) (node: Json) (value: Json) : string list =
    let get key = Json.tryGet key node

    let typeErrors =
        match get "type" with
        | Some(JString kind) ->
            let ok =
                match kind, value with
                | "string", JString _
                | "boolean", JBool _
                | "number", JNumber _
                | "object", JObject _
                | "array", JArray _
                | "null", JNull -> true
                | "integer", JNumber n -> n = Math.Floor n
                | _ -> false

            if ok then [] else [ sprintf "%s: expected %s" path kind ]
        | _ -> []

    let refErrors =
        match get "$ref" with
        | Some(JString reference) ->
            let name = reference.Substring("#/$defs/".Length)

            match defs () |> List.tryFind (fun (k, _) -> k = name) with
            | Some(_, target) -> validate path target value
            | None -> [ sprintf "%s: no definition %s" path name ]
        | _ -> []

    let enumErrors =
        match get "enum", get "const" with
        | Some(JArray values), _ when not (List.contains value values) -> [ sprintf "%s: %s is not one of the values" path (Json.stringify value) ]
        | _, Some expected when expected <> value -> [ sprintf "%s: expected %s" path (Json.stringify expected) ]
        | _ -> []

    let matching (schemas: Json list) =
        schemas |> List.filter (fun s -> (validate path s value).IsEmpty) |> List.length

    let combinationErrors =
        [
            match get "anyOf" with
            | Some(JArray options) when matching options = 0 -> yield sprintf "%s: matches none of anyOf" path
            | _ -> ()
            match get "oneOf" with
            | Some(JArray options) when matching options <> 1 ->
                // Say why the case its `type` names failed, when it names one.
                let named =
                    options
                    |> List.tryFind (fun option ->
                        match Json.tryGet "$ref" option with
                        | Some(JString r) ->
                            let def = defs () |> List.find (fun (k, _) -> "#/$defs/" + k = r) |> snd
                            Json.tryGet "const" (Json.get "type" (Json.get "properties" def)) = Json.tryGet "type" value
                        | _ -> false)

                match named with
                | Some option -> yield! validate path option value
                | None -> yield sprintf "%s: matches %d of oneOf" path (matching options)
            | _ -> ()
            match get "allOf" with
            | Some(JArray options) -> yield! options |> List.collect (fun s -> validate path s value)
            | _ -> ()
        ]

    let objectErrors =
        match value with
        | JObject members ->
            let properties =
                match get "properties" with
                | Some(JObject properties) -> properties
                | _ -> []

            [
                match get "required" with
                | Some(JArray required) ->
                    for key in required do
                        match key with
                        | JString key when not (List.exists (fun (k, _) -> k = key) members) -> yield sprintf "%s: missing %s" path key
                        | _ -> ()
                | _ -> ()
                for key, item in members do
                    match List.tryFind (fun (k, _) -> k = key) properties with
                    | Some(_, propertySchema) -> yield! validate (path + "." + key) propertySchema item
                    | None ->
                        match get "additionalProperties" with
                        | Some(JBool false) -> yield sprintf "%s: unknown key %s" path key
                        | Some(JObject _ as extra) -> yield! validate (path + "." + key) extra item
                        | _ -> ()
            ]
        | _ -> []

    let arrayErrors =
        match value, get "items" with
        | JArray items, Some itemSchema ->
            items
            |> List.mapi (fun i item -> validate (sprintf "%s[%d]" path i) itemSchema item)
            |> List.concat
        | _ -> []

    typeErrors
    @ refErrors
    @ enumErrors
    @ combinationErrors
    @ objectErrors
    @ arrayErrors

let private assertValid (label: string) (project: Json) =
    let errors = validate "$" schema.Value project
    Assert.True(errors.IsEmpty, sprintf "%s does not match schemas/project.schema.json:\n%s" label (errors |> List.truncate 20 |> String.concat "\n"))

let private example () =
    match ProjectFiles.load (repo [ "docs"; "examples"; "willow-lane" ]) with
    | Ok project -> project
    | Error errors -> failwith (String.concat "\n" errors)

[<Fact>]
let ``every template and every loadable fixture project matches the schema`` () =
    for template in ProjectCatalog.All do
        assertValid template (ProjectLoad.toJson (ProjectCatalog.CreateProjectForTemplate(template, fixedTime)))

    let fixtures =
        Directory.GetFiles(repo [ "fixtures"; "projects" ], "*.json")
        |> Array.append (Directory.GetFiles(repo [ "fixtures"; "parity" ], "*.json"))
        |> Array.sort

    let mutable checkedCount = 0

    for file in fixtures do
        let text = File.ReadAllText file

        match Json.parse text with
        | Ok json ->
            // Only the files that are projects which load (others are packs, content or broken on purpose).
            let candidates =
                [ json; Json.get "project" json ]
                |> List.filter (fun j -> Json.has "schemaVersion" j)

            for candidate in candidates do
                if (ProjectLoad.loadProject candidate).Ok then
                    checkedCount <- checkedCount + 1
                    assertValid (Path.GetFileName file) candidate
        | Error _ -> ()

    Assert.True(checkedCount >= 5, sprintf "only %d fixture projects checked" checkedCount)

[<Fact>]
let ``the worked example matches the schema as a single file`` () =
    match ProjectFiles.readSingleFileText (repo [ "docs"; "examples"; "willow-lane" ]) with
    | Ok text ->
        match Json.parse text with
        | Ok json -> assertValid "docs/examples/willow-lane" json
        | Error message -> failwith message
    | Error errors -> failwith (String.concat "\n" errors)

/// The record types `GameProject` reaches, by name.
let private reachableRecords () =
    let found = Collections.Generic.Dictionary<string, Type>()

    let rec visit (t: Type) =
        if t.IsGenericType then
            for a in t.GetGenericArguments() do
                visit a
        elif FSharpType.IsTuple t then
            for e in FSharpType.GetTupleElements t do
                visit e
        elif t.Namespace = typeof<GameProject>.Namespace && not (found.ContainsKey t.Name) then
            if FSharpType.IsRecord t then
                found.[t.Name] <- t

                for p in FSharpType.GetRecordFields t do
                    visit p.PropertyType
            elif FSharpType.IsUnion t then
                found.[t.Name] <- t

                for case in FSharpType.GetUnionCases t do
                    for f in case.GetFields() do
                        visit f.PropertyType

    visit typeof<GameProject>
    found

[<Fact>]
let ``the schema has every record and every key of the schema records`` () =
    let defs = defs ()
    let records = reachableRecords ()
    // Regenerate with: dotnet fsi tools/codegen/project-schema.fsx
    Assert.Equal<string list>(records.Keys |> List.ofSeq |> List.sort, defs |> List.map fst |> List.sort)

    for name, def in defs do
        let t = records.[name]

        if FSharpType.IsRecord t then
            let keys =
                FSharpType.GetRecordFields t
                |> Array.filter (fun p -> p.Name <> "Extra")
                |> Array.map (fun p ->
                    match Attribute.GetCustomAttribute(p, typeof<JsonKeyAttribute>) with
                    | :? JsonKeyAttribute as key -> key.Key
                    | _ -> string (Char.ToLowerInvariant p.Name.[0]) + p.Name.Substring 1)
                |> List.ofArray

            let properties =
                match Json.get "properties" def with
                | JObject properties ->
                    properties
                    |> List.map fst
                    |> List.filter (fun k -> k <> "type" || List.contains "type" keys)
                | _ -> []

            Assert.True((keys = properties), sprintf "%s: schema keys %A, record keys %A" name properties keys)

            let keepsExtra =
                FSharpType.GetRecordFields t |> Array.exists (fun p -> p.Name = "Extra")

            Assert.Equal(JBool keepsExtra, Json.get "additionalProperties" def)
    // JsonKey exceptions keep their spelling.
    let objective = defs |> List.find (fun (k, _) -> k = "QuestObjective") |> snd
    Assert.True(Json.has "targetNPCId" (Json.get "properties" objective))

[<Fact>]
let ``the worked example has no Problems at warning level or above and one of each thing`` () =
    let project = example ()

    let loud =
        Problems.collect project |> List.filter (fun p -> p.Severity <> Severity.Info)

    Assert.True(loud.IsEmpty, describe loud)
    // An event per trigger kind and a cutscene step of every type.
    Assert.Equal<string list>(List.sort EventTriggers.All, project.Events |> List.map _.Trigger |> List.distinct |> List.sort)

    let steps =
        defaultArg project.Cutscenes []
        |> List.collect _.Steps
        |> List.map _.Type
        |> List.distinct
        |> List.sort

    Assert.Equal<string list>(List.sort CutsceneStepTypes.All, steps)
    Assert.NotEmpty(defaultArg project.Mail [])
    Assert.NotEmpty(defaultArg project.HeartEvents [])
    let hazel = project.Npcs.Head
    Assert.NotEmpty(defaultArg hazel.Schedule [])
    Assert.NotEmpty(defaultArg hazel.Lines [])
    Assert.NotEmpty(defaultArg hazel.Portraits [])
